"/us/en/about/global-quality": {"template":"tier2-landing-page","metadata":{"title":"Global quality","pageTitle":null,"description":"At Stryker, quality is first in everything we do. Read our Quality Policy and learn more about how we build quality into our culture, our processes and our products.","image":"/content/dam/stryker/about/global-quality/images/GlobalQualityThumbnail.png","imageAlt":null,"tags":["quality","product_quality","supply_chain","manufacturing","regulatory","policy","supplier","certification","labeling"],"originallyPublished":"2023-02-06T20:34:15.000Z","lastPublished":"2026-06-19T17:41:22.000Z","contentID":"COMM-GSNPS-WEB-488150_REV-1"},"anchors":[{"id":"supplier-quality-management","title":"Supplier quality management","hidden":false,"type":"section-title","area":"customizablearea_parsys"}],"disclaimer":null,"forms":[],"tabs":[],"cardLists":[],"missingAlt":["/content/dam/stryker/about/global-quality/images/Hero_Image_Quality.jpg","/content/dam/stryker/about/global-quality/images/HERO_Cork inside-edit.jpg","/content/dam/stryker/about/global-quality/images/Icon5_Centered.jpg","/content/dam/stryker/about/global-quality/images/IconManufacturing_Centered.jpg","/content/dam/stryker/about/global-quality/images/medical-device-reprocessing.jpg","/content/dam/stryker/about/global-quality/images/medical_cary_gqo.jpg","/content/dam/stryker/about/global-quality/images/Icon4_Centered.jpg","/content/dam/stryker/about/global-quality/images/Icon2_Centered.jpg","/content/dam/stryker/about/global-quality/images/IconEthics_Centered.jpg"]},
"/us/en/about/governance": {"template":"tier2-landing-page","metadata":{"title":"Corporate governance","pageTitle":null,"description":"At Stryker we are committed to doing what’s right.  Good corporate governance is essential.  We conduct our affairs in compliance with all applicable laws and regulations and in accordance with the highest ethical standards.\r\n<br><br>\r\nAt the forefront of our organization is a winning team that measures the success of the Company not only by financial growth, but by how well we meet our own high standards of accountability. Our Board of Directors is elected annually and consists entirely of independent directors (with the exception of our Chair and CEO, Kevin Lobo).  Together, the Board of Directors combines education, experience and a rich history of commitment to Stryker in making decisions that benefit our Company, our shareholders, and ultimately, the lives of the patients we serve.","image":null,"imageAlt":null,"tags":[],"originallyPublished":"2023-02-06T21:47:52.000Z","lastPublished":"2026-07-13T18:51:54.000Z","contentID":"COMM-GSNPS-WEB-549850_Rev-2"},"anchors":[],"disclaimer":null,"forms":[],"tabs":[],"cardLists":[],"missingAlt":[]},
"/us/en/about/history": {"template":"tier2-landing-page","metadata":{"title":"Our history ","pageTitle":"Our history ","description":"When Dr. Homer Stryker, an orthopaedic surgeon from Kalamazoo, Michigan, USA, found that certain medical products were not meeting his patients’ needs, he invented new ones. As interest in these products grew, Dr. Stryker started a company in 1941 to produce them. The company’s goal was to help patients lead healthier, more active lives through products and services that make surgery and recovery simpler, faster and more effective.\r\n\r\nToday, we are one of the world's leading medical technology companies. Our growth comes from a diverse array of innovative products and services in Orthopaedics, Medical and Surgical, and Neurotechnology and Spine that help improve patient and hospital outcomes – which we achieve through the dedication of our ~33,000 employees globally in 2016.\r\n\r\nThe spirit of bringing innovation to healthcare began with Dr. Stryker when he founded the company in 1941 and it continues today. We are well-positioned to continue serving the worldwide medical community for generations to come. We think Dr. Stryker would be pleased.","image":null,"imageAlt":null,"tags":[],"originallyPublished":"2023-02-06T19:45:26.000Z","lastPublished":"2026-04-27T19:45:26.000Z","contentID":"COMM-GSNPS-WEB-597282_Rev-2"},"anchors":[],"disclaimer":null,"forms":[],"tabs":[],"cardLists":[],"missingAlt":[]},
