"/us/en/about/udi": {"template":"tier2-landing-page","metadata":{"title":"Unique Device Identification (UDI)","pageTitle":null,"description":"The U.S. Food and Drug Administration (FDA) created unique device identification, often abbreviated UDI, a rule that requires medical device manufacturers to update their products with a unique device identifier that includes both device and production identifiers (such as expiration date and lot or serial number).","image":null,"imageAlt":null,"tags":[],"originallyPublished":null,"lastPublished":"2017-08-29T13:52:20.000Z","contentID":"SYK CORP 2017-08-36"},"anchors":[{"id":"downloadstryker","title":"Download part information for Stryker products","hidden":false,"type":"section-title","area":"customizablearea_parsys"},{"id":"udi","title":"UDI","hidden":false,"type":"section-title","area":"customizablearea_parsys"},{"id":"gsone","title":"GS1","hidden":false,"type":"section-title","area":"customizablearea_parsys"},{"id":"providerimpact","title":"Provider impact","hidden":false,"type":"section-title","area":"customizablearea_parsys"}],"disclaimer":null,"forms":[],"tabs":[],"cardLists":[],"missingAlt":["/content/dam/stryker/about/udi/UDI_UDI_Sidebar.jpg","/content/dam/stryker/about/udi/GS1.jpg","/content/dam/stryker/about/udi/UDI_GS1_Sidebar.jpg","/content/dam/stryker/about/udi/gs1-128_linear_barcode.jpg","/content/dam/stryker/about/udi/2_gs1_barcodes.jpg","/content/dam/stryker/about/udi/2d_barcode.jpg"]},
