"/us/en/acute-care/c/caregiver-stories": {"template":"tier2-landing-page","metadata":{"title":"Caregiver Stories","pageTitle":null,"description":"They’re the nurses patients can never forget, the caregivers colleagues aspire to emulate, and the men and women who go above and beyond for their patients, giving of themselves in countless ways. They’re superheroes in scrubs, and we want to honor them for the incredible and inspiring work they do each and every day.","image":"/content/dam/stryker/campaigns/caregiver-stories/images/pam-mizerani/20210222-SYK_CGS_Tampa-322.jpg","imageAlt":"Pam Mizerany, RN and Debbie Ismer, RN","tags":[],"originallyPublished":"2023-02-06T01:12:58.000Z","lastPublished":"2026-08-13T17:21:43.000Z","contentID":null},"anchors":[{"id":"nominate","title":"Nominate a heroic healer","hidden":true,"type":"section-title","area":"customizablearea_parsys"},{"id":"honorees","title":"Honorees","hidden":true,"type":"section-title","area":"customizablearea_parsys"}],"disclaimer":"<p>Stryker Medical is <b>not</b> a business associate as that term is defined by The Health Insurance Portability and Accountability Act of 1996 (“HIPAA”). Please do <b>not</b> provide any Protected Health Information, as such term is defined by HIPAA.</p>","forms":[{"formId":"1232","afterSubmitAction":"showMessage","message":"Thank you for your nomination. If your nominee is selected, you will be notified by a Stryker employee. \r\n\r\nTogether with our customers, we are driven to make healthcare better.","useProduction":true}],"tabs":[],"cardLists":[],"missingAlt":[]},
