"/us/en/emergency-care/c/ems-world-trade-show": {"template":"tier2-landing-page","metadata":{"title":"EMS World 2027 Trade Show","pageTitle":null,"description":"Ready to get hands-on with some of our products? Join Stryker at EMS World from September 27 to October 1 in New Orleans.","image":"/content/dam/stryker/acute-care/campaigns/ena-trade-show/new-orleans-skyline-at-night_1920x640.jpg","imageAlt":"A skyline view of downtown New Orleans at dusk","tags":["stryker:business-unit/ems"],"originallyPublished":"2024-08-14T15:36:18.000Z","lastPublished":"2026-10-06T15:25:50.000Z","contentID":"EC-GSNPS-SYK-1212552_REV-4_en_us"},"anchors":[{"id":"overview","title":"Overview","hidden":true,"type":"section-title","area":"customizablearea_parsys"},{"id":"connect","title":"Connect","hidden":true,"type":"section-title","area":"customizablearea_parsys"}],"disclaimer":null,"forms":[{"formId":"1275","afterSubmitAction":"showMessage","message":"Thanks!","useProduction":true}],"tabs":[],"cardLists":[],"missingAlt":[]},
"/us/en/emergency-care/c/fdic-trade-show": {"template":"tier2-landing-page","metadata":{"title":"FDIC Tradeshow","pageTitle":"FDIC Tradeshow 2027","description":"Experience Stryker at FDIC 2027. FDIC provides a unique and unparalleled experience for Fire & Rescue professionals worldwide, featuring top-notch instructors, workshops, innovative products and a platform for formal and informal peer learning, fostering friendships and reigniting passion for the industry.","image":"/content/dam/stryker/ems/tradeshows/images/indiana-convention-center-hero_1200x680.jpg","imageAlt":"Exterior view of the Indianapolis convention center","tags":["stryker:business-unit/ems","stryker:business-unit/acute-care"],"originallyPublished":"2023-02-06T10:45:32.000Z","lastPublished":"2026-08-13T20:48:39.000Z","contentID":"EC-GSNPS-SYK-1102182_REV-3_en_us"},"anchors":[{"id":"overview","title":"Overview","hidden":true,"type":"section-title","area":"customizablearea_parsys"},{"id":"must-see","title":"Must-see at FDIC","hidden":false,"type":"section-title","area":"customizablearea_parsys"},{"id":"connect","title":"Connect","hidden":true,"type":"section-title","area":"customizablearea_parsys"}],"disclaimer":"<p>LIFENET Care and LIFENET Care App, is a data transmission system, designed to facilitate communication between EMS and hospital staff. LIFENET is not intended to be used to make remote diagnostic or patient care decisions—patient care decisions are made by the healthcare provider on scene based on actual patient assessment.</p>","forms":[{"formId":"1275","afterSubmitAction":"showMessage","message":"Thanks!","useProduction":true}],"tabs":[],"cardLists":[{"component":"customizable","title":null,"items":[{"path":"/us/en/emergency-care/products/lifepak-35","resolved":true,"title":"LIFEPAK 35 monitor/defibrillator","description":"The LIFEPAK 35 monitor/defibrillator for hospitals and EMS is a future-ready device designed to promote confident cardiac care, enable clinical excellence and deliver in demanding environments.","image":"/content/dam/stryker/ems/products/lifepak-35/images/LIFEPAK-35-Hero-angled-left_1200x680.jpg","alt":"LIFEPAK 35 monitor/defibrillator for hospital and EMS"},{"path":"/us/en/emergency-care/products/lifepak-cr2","resolved":true,"title":"LIFEPAK CR2 defibrillator ","description":"The LIFEPAK CR2 AED response system empowers bystanders to help save lives. Innovative, easy-to-operate technology allows continuous CPR and helps streamline communication across the system of care.","image":"/content/dam/stryker/ems/products/lifepak-cr2/LP_CR2.jpg","alt":"LIFEPAK CR2 defibrillator "},{"path":"/us/en/emergency-care/products/lucas-3","resolved":true,"title":"LUCAS 3, v3.1 chest compression system","description":"Deliver high-performance, continuous chest compressions.","image":"/content/dam/stryker/ems/products/lucas-3/Lucas_3_2.jpg","alt":"Automatic CPR machine - LUCAS 3, v3.1 chest compression system"},{"path":"/us/en/emergency-care/products/lifenet-system","resolved":true,"title":"LIFENET System","description":"The LIFENET System is a comprehensive cloud-based platform that intelligently manages and delivers patient information and device data EMS and hospital teams need to work together seamlessly.","image":"/content/dam/stryker/ems/products/lifenet/LIFENET-LP35_callout-thumbnail_470x300.jpg","alt":"LIFEPAK 35 unit in front of monitor displaying LIFENET System screen"}]},{"component":"customizable_copy_co","title":null,"items":[{"path":"/us/en/emergency-care/products/lifenet-care","resolved":true,"title":"LIFENET Care","description":"Get a more unified view of your patient's journey by customizing protocols on a modern, clean interface. LIFENET Care makes it easy to consolidate patient data, organize your workflow and connect care teams to make your job easier.","image":"/content/dam/stryker/ems/products/lifenet-care/images/lifenet-care-thumbnail-2.png","alt":"LIFENET Care screen on a computer "},{"path":"/us/en/emergency-care/products/power-pro-2","resolved":true,"title":"Power-PRO 2 powered ambulance cot","description":"Lift, lower and transport with confidence. Power-PRO 2 is the first connected ambulance cot, built for the relentless workload of emergency response.","image":"/content/dam/stryker/ems/products/power-pro-2/images/Thumbnail_Power-PRO_2_307x184.jpg","alt":"Power-PRO 2"},{"path":"/us/en/emergency-care/products/power-load","resolved":true,"title":"Power-LOAD","description":"Our Power-LOAD cot fastener improves operator and patient safety by supporting the cot throughout the loading and unloading process.","image":"/content/dam/stryker/ems/products/power-load/images/Thumbnail_Power_LOAD.jpg","alt":"Power-LOAD"},{"path":"/us/en/emergency-care/products/xpedition-powered-stair-chair","resolved":true,"title":"Xpedition powered stair chair","description":"Xpedition, Stryker's first powered stair chair, has uniquely designed features to help decrease your effort while transporting patients and increase your patients' comfort – because the journey is just as important as the destination.","image":"/content/dam/stryker/ems/products/xpedition/images/Thumbnail_Xpedition_307x184_Transparent.png","alt":"Xpedition powered patient transport chair "}]}],"missingAlt":[]},
