"/us/en/emergency-care/c/the-art-of-triage-preparing-for-chemical-warfare-agents": {"template":"tier2-landing-page","metadata":{"title":"The art of triage: Preparing for chemical warfare agents","pageTitle":null,"description":"This lecture will focus on a toxidrome-based method of triage to rapidly identify the most lethal and rapidly acting toxins that can be used in a chemical attack. We will discuss how the information gained during this process will have direct implications for management of casualties first identified in the prehospital environment.  We will also review commonly discussed mass casualty incident (MCI) triage tools and how they can be incorporated during these complex events. ","image":null,"imageAlt":null,"tags":[],"originallyPublished":"2024-11-13T21:05:06.000Z","lastPublished":"2024-11-28T12:54:30.000Z","contentID":"EC-ECCL-COMM-1426256_REV-0_en_us "},"anchors":[],"disclaimer":null,"forms":[],"tabs":[],"cardLists":[],"missingAlt":[]},
