"/us/en/foot-and-ankle/products/anchorage-2/anchorage2-video-library": {"template":"tier2-landing-page","metadata":{"title":"Anchorage 2 CP video library","pageTitle":"Anchorage 2 CP video library","description":"The Anchorage 2 CP system is intended for use in internal fixation, reconstruction and treatment of fractures in the foot and ankle in adult and adolescent patients (12-21 years). Indications include: Replantation, joint fusions, corrective osteotomies and osteopenic bone. ","image":null,"imageAlt":null,"tags":["stryker:portfolio/orthopaedics"],"originallyPublished":"2026-01-28T18:09:55.000Z","lastPublished":"2026-01-28T18:10:22.000Z","contentID":"FA-ANC2-SYK-2572550_REV-0_en_us"},"anchors":[],"disclaimer":null,"forms":[],"tabs":[],"cardLists":[],"missingAlt":[]},
"/us/en/foot-and-ankle/products/prostep/video-library": {"template":"tier2-landing-page","metadata":{"title":"PROstep Video Library","pageTitle":"PROstep Video Library","description":"Video library for PROstep. Delivered by Stryker, the leader in foot and ankle, PROstep minimally invasive surgery helps you give patients the bunion pain relief they need, while also providing the faster recovery they desire. PROSTEP MIS utilizes percutaneous, micro incisions to correct bunions as well as perform a multitude of forefoot, midfoot and hindfoot procedures. These procedures include: hammertoe, DMMO, bunionette, calcaneal osteotomies, MIS arthrodesis and joint fusion, and many more. (2,3,5) (Wright Medical)","image":"/content/dam/stryker/foot-and-ankle/products/prostep/HERO_PROstep MICA Foot_LG.png","imageAlt":null,"tags":[],"originallyPublished":"2023-02-06T15:26:05.000Z","lastPublished":"2024-06-28T18:12:29.000Z","contentID":null},"anchors":[{"id":"new","title":"New","hidden":false,"type":"section-title","area":"customizablearea_parsys"}],"disclaimer":null,"forms":[],"tabs":[],"cardLists":[],"missingAlt":[]},
