"/us/en/services-and-solutions/onsite": {"template":"tier2-landing-page","metadata":{"title":"OnSite Services","pageTitle":null,"description":"We understand the unique challenges and difficult demands that you manage on a daily basis. OnSite offers customized workflow solutions to mitigate these challenges within the operating room and sterile processing department, so your staff can focus on what they do best – caring for patients. \r\n<br><br>\r\n<a href='/content/stryker/us/en/endoscopy/contact.html'>Contact your local Endoscopy Sales Representative</a> for more information about our managed service opportunities.","image":"/content/dam/stryker/services/onsite/Thumbnail_OnSite-Hero-BUv2.jpg","imageAlt":null,"tags":["stryker:content-type/hcp_content","stryker:services/onsite"],"originallyPublished":"2023-02-06T20:10:39.000Z","lastPublished":"2026-07-10T20:58:48.000Z","contentID":"ENDO-GSNPS-OTHW-1719363"},"anchors":[{"id":"contact","title":"Contact","hidden":true,"type":"section-title","area":"customizablearea_parsys"}],"disclaimer":"<p>1. Stryker OnSite Customer Implementation Survey, 2016.</p>","forms":[{"formId":"2174","afterSubmitAction":"showMessage","message":"Thank you for your submission. We will get back to you as soon as possible. ","useProduction":true},{"formId":"4047","afterSubmitAction":"showMessage","message":"Thank you! We have received your request. A Stryker representative will be in contact with you soon.","useProduction":true}],"tabs":[],"cardLists":[],"missingAlt":[]},
"/us/en/services-and-solutions/procare": {"template":"tier2-landing-page","metadata":{"title":"ProCare Services","pageTitle":null,"description":"We are dedicated to being your trusted and proactive service partner – providing flexible service solutions to help maximize uptime without sacrificing safety for savings. We provide unmatched service as the original equipment manufacturer - with original Stryker parts, proprietary product knowledge and our team of expert service professionals.","image":"/content/dam/stryker/services/procare/images/procare-thumbnail.png","imageAlt":"ProCare","tags":["stryker:content-type/hcp_content","stryker:services/procare"],"originallyPublished":"2023-02-06T20:51:46.000Z","lastPublished":"2026-08-06T15:44:57.000Z","contentID":"CORPM-GSNPS-SYK-2137337_REV-1"},"anchors":[{"id":"purpose","title":"Our Purpose","hidden":true,"type":"section-title","area":"customizablearea_parsys"},{"id":"about","title":"About us","hidden":true,"type":"section-title","area":"customizablearea_parsys"},{"id":"advantage","title":"procare advantage","hidden":true,"type":"section-title","area":"customizablearea_parsys"},{"id":"equipment","title":"Covered equipment","hidden":true,"type":"section-title","area":"customizablearea_parsys"}],"disclaimer":null,"forms":[],"tabs":[["Maximizing uptime","Flexible service solutions","OEM Quality and Reliability","Clinical workflow efficiency"]],"cardLists":[],"missingAlt":[]},
"/us/en/services-and-solutions/reprocessing-and-remanufacturing": {"template":"tier2-landing-page","metadata":{"title":"Reprocessing in healthcare","pageTitle":null,"description":"Reprocessing of single-use medical devices (SUDs) is the practice of inspecting, cleaning, function testing, packaging and sterilizing so that they can be clinically and safely used again. Reprocessing of SUDs is regulated by the FDA. We satisfy all FDA regulatory requirements to reprocess medical devices and ensure that our reprocessed devices are substantially equivalent to original equipment devices.","image":"/content/dam/stryker/services/reprocessing-and-remanufacturing/images/Thumbnail_Reprocessing_Remanufacturing_Retina_transparentBG.jpg","imageAlt":null,"tags":["stryker:services/reprocessing-and-remanufacturing","stryker:content-type/hcp_content"],"originallyPublished":"2026-01-29T20:50:51.000Z","lastPublished":"2026-08-19T20:19:38.000Z","contentID":"CORPM-GSNPS-SYK-1910250"},"anchors":[{"id":"reprcoessed","title":"What is reprocessing? ","hidden":false,"type":"section-title","area":"customizablearea_parsys"}],"disclaimer":null,"forms":[{"formId":"2736","afterSubmitAction":"showMessage","message":"Thank you! We have received your request. A Stryker representative will be in contact with you soon.","useProduction":true}],"tabs":[],"cardLists":[],"missingAlt":[]},
