"/us/en/training-and-education/orthopaedics/joint-replacement/a-commitment-to-surgeon-education": {"template":"tier2-landing-page","metadata":{"title":"A Commitment to Surgeon Education","pageTitle":null,"description":"We believe that broadening your experience and knowledge through the latest educational programs and technologies allows Stryker to help improve healthcare worldwide. Our goal is to develop meaningful learning opportunities that meet your unique needs at every stage of you career.\r\n\r\nOur integrated programs and education innovations targeting surgeons residents and fellows can be used to forge a personalized education pathway that meets your specific education goals, appeals to your personal learning style and fits within your busy schedule. Review the options below with your Stryker sales representative and work together to create your personalized Education Pathway.","image":"/content/dam/stryker/joint-replacement/images/Joint_Pres.png","imageAlt":null,"tags":[],"originallyPublished":"2023-02-06T14:13:14.000Z","lastPublished":"2026-05-26T18:34:11.000Z","contentID":"JR-GSNPS-SYK-1779400_REV-1"},"anchors":[{"id":"sta","title":"Stryker's Training Academy","hidden":true,"type":"section-title","area":"customizablearea_parsys"},{"id":"peer-to-peer","title":"Peer-to-Peer Learning","hidden":true,"type":"section-title","area":"customizablearea_parsys"},{"id":"residents-and-fellows","title":"Residents and Fellows","hidden":true,"type":"section-title","area":"customizablearea_parsys"},{"id":"calendar","title":"Global Medical Education Calendar","hidden":true,"type":"section-title","area":"customizablearea_parsys"}],"disclaimer":null,"forms":[],"tabs":[],"cardLists":[],"missingAlt":[]},
